<script lang="ts">
import {nextSort,sortRows,type SortKey} from './table-sort';
import {translatedName} from './localization';

 import {languageOverrides} from "./localization";
 import {onDestroy} from 'svelte';import {reportEditorDirty} from './editor-drafts';
 import {type Project,type PaymentBatch,uid} from './model';import {D} from './engine';
 import {previewBatchRow,savePaymentBatch,applyPaymentDetail,type PaymentDetailRequest} from './payment-batches';
 import {accountOpenInMonth} from './account-lifecycle';import {openReportLookup} from './report-settings';
 import {translator} from './i18n';import {issueText} from './validation-language';import {ZodError} from 'zod';
 import {Search,RotateCcw,Plus,Copy,Trash2,ArrowUp,ArrowDown,Users,Eye,Save,Check,X,FileText} from "./icons";
 export let project:Project;export let initial:PaymentBatch;export let editorId:string;
 export let onapply:(p:Project)=>void;export let onclose:()=>void;export let ondetails:(request:PaymentDetailRequest)=>void;export let onmovements:(id:string)=>void;
 export let beforeSave:()=>Promise<boolean>=async()=>true;
 let draft=structuredClone(initial),selected='',error='',query='';let sortKeys:SortKey[]=[];let editor:HTMLDivElement;let savedDraft=JSON.stringify(draft);
 $:t=translator(project.settings.language,$languageOverrides);$:locked=draft.state==='applied';
 $:total=draft.rows.reduce((sum,row)=>{try{return sum.plus(row.amount);}catch{return sum;}},D(0)).toFixed(2);
 $:reportEditorDirty(editorId,!locked&&(!project.payment_batches.some(b=>b.id===draft.id)||JSON.stringify(draft)!==savedDraft));
 onDestroy(()=>reportEditorDirty(editorId,false));

 function rowCell(value:PaymentBatch['rows'][number],column:number):string{const account=project.accounts.find(a=>a.id===value.account_id);return column===0?String(draft.rows.indexOf(value)+1):column===1?(account?.number||'')+', '+(account?.payer_name||''):column===2?value.amount:column===3?String(Number(value.source_automatic??value.manual_maintenance===null)):column===4&&draft.imported?String(Number(!!value.source_advance)):value.manual_maintenance===null?'automatic':'manual';}
 $:visibleRows=sortRows(draft.rows.filter(value=>rowCell(value,1).toLocaleLowerCase().includes(query.toLocaleLowerCase())),sortKeys,rowCell);
 function sortColumn(column:number,event:MouseEvent){sortKeys=nextSort(sortKeys,column,event.shiftKey);}
 $:columns=[{key:0,label:'№'},{key:1,label:t('Лицевой счёт','Cont personal')},{key:2,label:t('Сумма платежа','Suma plății')},{key:3,label:t('Распределять оплату автоматически','Repartizare automată')},...(draft.imported?[{key:4,label:t('Переплата на аванс','Supraplată în avans')}]:[]),{key:draft.imported?5:4,label:t('Способ распределения','Metodă de repartizare')}];
 function navigateAmount(e:KeyboardEvent,id:string){if(e.key!=='Enter')return;e.preventDefault();e.stopPropagation();const index=visibleRows.findIndex(row=>row.id===id),next=index+(e.shiftKey?-1:1),value=visibleRows[next];if(value){selected=value.id;const input=editor.querySelector<HTMLInputElement>('[data-payment-amount="'+CSS.escape(value.id)+'"]');input?.focus();input?.select();}else if(!e.shiftKey){editor.querySelector<HTMLInputElement>('.comment input')?.focus();}}
 function describe(e:unknown){return e instanceof ZodError?e.issues.slice(0,3).map(i=>issueText(i,project.settings.language)).join('; '):e instanceof Error?e.message:String(e);}
 function row(accountId:string){return {id:uid(),account_id:accountId,amount:'0.00',manual_maintenance:null,payment_id:null};}
 function add(){const account=project.accounts.find(a=>!draft.rows.some(r=>r.account_id===a.id));if(account){const value=row(account.id);draft.rows=[...draft.rows,value];selected=value.id;}}
 function fill(ids?:Set<string>){const used=new Set(draft.rows.map(r=>r.account_id));draft.rows=[...draft.rows,...project.accounts.filter(a=>!used.has(a.id)&&(ids?ids.has(a.id):accountOpenInMonth(a,draft.date.slice(0,7)))).map(a=>row(a.id))];}
 function pick(){openReportLookup({id:editorId+'-accounts',parentId:editorId,label:t('Лицевые счета','Conturi personale'),kind:'accounts',items:[],selected:[],multiple:true,onchoose:ids=>{if(!locked)fill(new Set(ids));}});}
 function method(){openReportLookup({id:editorId+'-method',parentId:editorId,label:t('Варианты оплаты','Modalități de plată'),kind:'payment-methods',items:[],selected:[],multiple:false,onchoose:ids=>{if(!locked)draft.method=project.reference_catalogs['payment-methods']?.find(r=>r.id===ids[0])?.name||draft.method;}});}
 function move(direction:number){const rows=[...draft.rows],i=rows.findIndex(r=>r.id===selected),j=i+direction;if(i<0||j<0||j>=rows.length)return;[rows[i],rows[j]]=[rows[j],rows[i]];draft.rows=rows;}
 function copy(){const original=draft.rows.find(r=>r.id===selected),account=project.accounts.find(a=>!draft.rows.some(r=>r.account_id===a.id));if(original&&account){const value={...original,id:uid(),account_id:account.id,payment_id:null};draft.rows=[...draft.rows,value];selected=value.id;}}
 function automatic(value:PaymentBatch['rows'][number]){try{value.manual_maintenance=value.manual_maintenance!==null?null:previewBatchRow(project,draft,value).find(s=>s.service_id===draft.balancing_service_id)?.amount||'0.00';error='';}catch(e){error=describe(e);}}
 function detail(rowId:string){if(!draft.rows.some(r=>r.id===rowId))return;const expected=structuredClone(draft);ondetails({parentId:editorId,batch:expected,rowId,onapply:(amount,manual)=>{draft=applyPaymentDetail(project,draft,expected,rowId,amount,manual);}});}
 async function save(post=false,close=false){if(!(await beforeSave()))return;try{const next=savePaymentBatch(project,draft,post);onapply(next);draft=structuredClone(next.payment_batches.find(b=>b.id===draft.id)!);savedDraft=JSON.stringify(draft);reportEditorDirty(editorId,false);error='';if(close)onclose();}catch(e){error=describe(e);}}
</script>
<div class="batch-editor" bind:this={editor}>
 {#if error}<p class="alert error" role="alert">{error}</p>{/if}
 <fieldset disabled={locked}>
  <div class="header-fields"><label>{t('Дата','Data')}<input type="date" bind:value={draft.date}/></label><label>{t('Номер','Număr')}<input bind:value={draft.number}/></label></div>
  <label class="method"><span>{t('Вариант оплаты','Modalitate de plată')}</span><div><input bind:value={draft.method}/><button title={t('Выбрать вариант оплаты','Selectează modalitatea de plată')} onclick={method}>…</button><button title={t('Очистить','Golește')} onclick={()=>draft.method=''}><X size={15}/></button><button title={t('Найти вариант оплаты','Caută modalitatea de plată','Find payment method')} onclick={method}><Search size={15}/></button></div></label>
 </fieldset>
 <div class="line-toolbar" role="toolbar" aria-label={t('Строки оплаты','Rânduri de plată')}>
  <button disabled={locked} title={t('Добавить','Adaugă')} onclick={add}><Plus size={17}/></button><button disabled={locked||!selected} title={t('Копировать строку','Copiază rândul')} onclick={copy}><Copy size={17}/></button><button disabled={locked||!selected} title={t('Удалить строку','Elimină rândul')} onclick={()=>{draft.rows=draft.rows.filter(r=>r.id!==selected);selected='';}}><Trash2 size={17}/></button>
  <button disabled={locked||!selected} title={t('Вверх','Sus')} onclick={()=>move(-1)}><ArrowUp size={17}/></button><button disabled={locked||!selected} title={t('Вниз','Jos')} onclick={()=>move(1)}><ArrowDown size={17}/></button>
  <button disabled={locked} onclick={pick}><Users size={16}/>{t('Подбор','Selectare')}</button><button disabled={locked} onclick={()=>fill()}><Plus size={16}/>{t('Заполнить','Completează')}</button><button disabled={locked} onclick={()=>{draft.rows=[];selected='';}}><X size={16}/>{t('Очистить','Golește')}</button>
  <button class="details-command" disabled={!selected} onclick={()=>detail(selected)}><Eye size={16}/>{t('Расшифровка платежа','Repartizarea plății')}</button>
 </div>
 <div class="batch-search"><label><Search size={16}/><input bind:value={query} placeholder={t('Поиск по лицевому счёту или имени','Caută după cont sau nume','Search account or name')} aria-label={t('Поиск','Căutare')}/></label><button class="button secondary" disabled={!sortKeys.length} onclick={()=>sortKeys=[]}><RotateCcw size={15}/>{t('Сброс сортировки','Resetează sortarea','Reset sorting')}</button></div>
 <div class="table-wrap"><table><thead><tr>{#each columns as column}<th aria-sort={sortKeys.find(k=>k.column===column.key)?.direction===1?'ascending':sortKeys.find(k=>k.column===column.key)?.direction===-1?'descending':'none'}><button class="batch-sort" onclick={e=>sortColumn(column.key,e)}>{column.label}<span class="sort-arrow" class:sort-active={sortKeys.some(k=>k.column===column.key)}>{sortKeys.find(k=>k.column===column.key)?.direction===-1?'↓':'↑'}{sortKeys.length>1&&sortKeys.some(k=>k.column===column.key)?sortKeys.findIndex(k=>k.column===column.key)+1:''}</span></button></th>{/each}</tr></thead><tbody>{#each visibleRows as row,i (row.id)}<tr class:selected={selected===row.id} class:attention-row={!locked&&(!row.account_id||row.amount==='')} onclick={()=>selected=row.id} ondblclick={()=>detail(row.id)}><td>{i+1}</td><td>{#if locked}{project.accounts.find(a=>a.id===row.account_id)?.number}, {project.accounts.find(a=>a.id===row.account_id)?.payer_name}{:else}<select bind:value={row.account_id} aria-label={t('Лицевой счёт строки ','Contul din rândul ')+(i+1)}>{#each project.accounts as a}<option value={a.id}>{a.number}, {a.payer_name}</option>{/each}</select>{/if}</td><td><input disabled={locked} data-payment-amount={row.id} onkeydown={e=>navigateAmount(e,row.id)} bind:value={row.amount} aria-label={t('Сумма строки ','Suma rândului ')+(i+1)}/></td><td class="checkbox-cell"><input disabled={locked} type="checkbox" checked={row.source_automatic??row.manual_maintenance===null} onchange={()=>automatic(row)} aria-label={t('Автоматическое распределение строки ','Repartizare automată în rândul ')+(i+1)}/></td>{#if draft.imported}<td class="checkbox-cell"><input type="checkbox" disabled checked={row.source_advance||false} aria-label={t('Переплата на аванс','Supraplată în avans')}/></td>{/if}<td>{draft.imported?t('Сохранённое распределение','Repartizare păstrată'):row.manual_maintenance===null?t('Пропорционально долгу','Proporțional datoriei'):t('Обслуживание вручную','Deservire manuală')}</td></tr>{/each}</tbody><tfoot><tr><th colspan="2">{t('Итого','Total')}</th><td>{total}</td><td colspan={draft.imported?3:2}></td></tr></tfoot></table></div>
 <fieldset disabled={locked}><label class="comment"><span>{t('Комментарий','Comentariu')}</span><input bind:value={draft.comment}/></label>{#if !draft.imported}<details open={!draft.balancing_service_id&&!locked}><summary>{t('Параметры распределения','Parametri de repartizare')}</summary><div class="header-fields"><label>{t('Долг по месяц включительно','Datorie până la luna inclusiv')}<input type="month" bind:value={draft.billing_through}/></label><label>{t('Услуга обслуживания дома','Serviciul de deservire a blocului')}<select bind:value={draft.balancing_service_id}><option value="">{t('Выберите услугу','Selectați serviciul')}</option>{#each project.services as s}<option value={s.id}>{translatedName(s.name,project.settings.language,$languageOverrides)}</option>{/each}</select></label></div></details>{/if}</fieldset>
 <footer><button class="button secondary movements" onclick={()=>onmovements(draft.id)} disabled={!project.payment_batches.some(b=>b.id===draft.id)}><FileText size={16}/>{t('Движения','Înregistrări')}</button>{#if !locked}<button class="button" onclick={()=>save(true,true)}><Check size={16}/>OK</button><button class="button secondary" onclick={()=>save()}><Save size={16}/>{t('Сохранить','Salvează')}</button>{/if}<button class="button secondary" onclick={onclose}><X size={16}/>{t('Закрыть','Închide')}</button></footer>
</div>




<style>
.batch-editor{display:flex;flex-direction:column;gap:12px;padding:14px;min-width:0;box-sizing:border-box}fieldset{border:0;padding:0;margin:0;min-width:0;display:flex;flex-direction:column;gap:12px}.header-fields{display:flex;gap:16px;flex-wrap:wrap}label{display:flex;flex-direction:column;gap:5px}.method,.comment{display:grid;grid-template-columns:140px minmax(0,1fr);align-items:center;gap:12px}.method>div{display:flex;min-width:0}.method input,.comment input{min-width:0;width:100%;box-sizing:border-box}.method button{width:34px;flex-shrink:0;display:grid;place-items:center;background:var(--surface);color:var(--text);border:1px solid var(--border)}.line-toolbar,footer{display:flex;align-items:center;gap:4px;flex-wrap:wrap}.line-toolbar button{display:flex;align-items:center;gap:5px;min-height:32px;border:0;padding:5px 7px;background:transparent;color:var(--text)}.line-toolbar button:hover{background:var(--hover)}.details-command{margin-left:auto}.table-wrap{overflow:auto;max-height:52vh}table{width:100%;min-width:720px;border-collapse:collapse}th,td{padding:7px;text-align:left}th{background:var(--surface);position:sticky;top:0;z-index:1}td select{width:100%;min-width:220px;box-sizing:border-box}td input:not([type=checkbox]){width:110px;text-align:right;box-sizing:border-box}.checkbox-cell{text-align:center}.selected{background:#489bcb30}footer{justify-content:flex-end;gap:8px}.movements{margin-right:auto}details>div{padding:12px 0}summary{padding:8px;cursor:pointer}

:global(.desktop-window-content:has(>.batch-editor)){overflow:hidden;display:flex;flex-direction:column}
.batch-editor{flex:1;height:100%;min-height:0;gap:8px;background:var(--bg);padding:12px}
.batch-editor>fieldset,.line-toolbar,.batch-search,.batch-editor>footer{flex:none;background:var(--surface);padding:10px;border:1px solid var(--border);border-radius:3px}
.batch-editor>.table-wrap{flex:1;min-height:70px;max-height:none;overflow:auto!important;border:1px solid var(--border);background:var(--surface)}
.batch-editor .line-toolbar button{background:color-mix(in srgb,var(--surface) 88%,var(--accent));border:1px solid var(--border);border-radius:2px;margin:1px;padding:6px 9px}
.batch-editor .line-toolbar button:hover{background:var(--hover)}
.batch-search{display:flex;align-items:center;gap:10px}.batch-search label{display:flex;flex:1;flex-direction:row;align-items:center;gap:8px}.batch-search input{min-width:80px;width:100%;height:32px}.batch-search button{min-height:32px}
.batch-editor>footer{margin:0;position:relative;z-index:2}.batch-editor>.table-wrap th{background:color-mix(in srgb,var(--surface) 92%,var(--accent));padding-block:10px}

.batch-sort{width:100%;text-align:left;font:inherit;font-weight:inherit;background:transparent;color:inherit;border:0;padding:0;cursor:pointer}.sort-arrow{opacity:0;color:var(--muted);margin-left:5px}.batch-sort:hover .sort-arrow,.batch-sort:focus-visible .sort-arrow,.sort-arrow.sort-active{opacity:1}</style>
